window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c0c9d70b71f0ac14"]={"versions": [{"id": "FIG-c0c9d70b71f0ac14", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd FrNm_Shutdown</code>) zur Darstellung des Shutdown-Ablaufs im FlexRay-Netzwerkmanagement (<code>FrNm</code>). Das Diagramm zeigt den Übergang von aktiven Betriebszuständen in den Bus-Sleep-Modus und die Interaktion zwischen <code>FrNm</code> und der allgemeinen Netzwerkmanagement-Schicht (<code>Nm</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind die Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>Nm::Nm</code>: Generische Netzwerkmanagement-Komponente.\n</li><li><code>Nm:Nm Callbacks</code>: Callback-Schnittstelle der generischen Netzwerkmanagement-Komponente.\n</li><li><code>FrNm::FrNm</code>: FlexRay-spezifisches Netzwerkmanagement-Modul.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Funktionsaufrufe:</p>\n<ul class=\"fig-list\"><li>Synchroner Aufruf <code>Nm_BusSleepMode(Nm_ChannelHandleType)</code> von <code>FrNm::FrNm</code> an <code>Nm:Nm Callbacks</code> mit anschließender gestrichelter Rückkehrnachricht.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>FrNm::FrNm</code> befindet sich initial im Modus <code>Network Mode</code> (Substatus <code>Network Released</code>) sowie im Zustand <code>Ready Sleep State</code>.\n</li><li><code>FrNm::FrNm</code> initiiert den Shutdown und ruft auf der Callback-Lebenslinie von <code>Nm</code> synchron <code>Nm_BusSleepMode(Nm_ChannelHandleType)</code> auf.\n</li><li>Nach Beendigung der Ausführungsausprägung auf <code>Nm</code>-Seite erfolgt die gestrichelte Rückkehr zu <code>FrNm::FrNm</code>.\n</li><li><code>FrNm::FrNm</code> wechselt in den Modus <code>Bus Sleep Mode</code> bei weiterhin freigegebenem Netzwerk (<code>Network Released</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Implementierer von <code>FrNm</code> ist der Aufruf von <code>Nm_BusSleepMode</code> mit dem Kanal-Handle (<code>Nm_ChannelHandleType</code>) beim Übergang aus dem <code>Ready Sleep State</code> in den <code>Bus Sleep Mode</code> verbindlich, um die übergeordnete <code>Nm</code>-Schicht über das Erreichen des Ruhezustands zu benachrichtigen.</p>"}, {"id": "FIG-fd4855bed9d20f73", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd FrNm_Shutdown</code>) zur Darstellung des Shutdown-Ablaufs im FlexRay-Netzwerkmanagement (<code>FrNm</code>). Das Diagramm zeigt den Übergang von aktiven Betriebszuständen in den Bus-Sleep-Modus und die Interaktion zwischen <code>FrNm</code> und der allgemeinen Netzwerkmanagement-Schicht (<code>Nm</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind die als BSW-Module typisierten Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>«module» Nm::Nm</code>: Generische Netzwerkmanagement-Komponente.\n</li><li><code>«module» FrNm::FrNm</code>: FlexRay-spezifisches Netzwerkmanagement-Modul.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Funktionsaufrufe:</p>\n<ul class=\"fig-list\"><li>Synchroner Funktionsaufruf <code>Nm_StateChangeNotification()</code> von <code>FrNm::FrNm</code> an <code>Nm::Nm</code>.\n</li><li>Rückkehrnachricht mit Beschriftung <code>Nm_StateChangeNotification()</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>FrNm::FrNm</code> befindet sich initial im Modus <code>Network Mode</code> (Zustand <code>Network Released</code>) sowie im <code>Repeat Message State</code>.\n</li><li><code>FrNm::FrNm</code> ruft <code>Nm_StateChangeNotification()</code> auf der Lebenslinie <code>Nm::Nm</code> auf.\n</li><li>Nach Durchlaufen des Aktivierungsbalkens auf <code>Nm::Nm</code> erfolgt die gestrichelte Rückkehrnachricht (beschriftet mit <code>Nm_StateChangeNotification()</code>) zurück zu <code>FrNm::FrNm</code>.\n</li><li><code>FrNm::FrNm</code> nimmt den Modus <code>Bus Sleep Mode</code> bei freigegebenem Netzwerk (<code>Network Released</code>) ein.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Implementierer von <code>FrNm</code> müssen sicherstellen, dass Zustandsänderungen beim Übergang in den <code>Bus Sleep Mode</code> über die generische Callback-Funktion <code>Nm_StateChangeNotification()</code> an die <code>Nm</code>-Schicht gemeldet werden. Die Benachrichtigung erfolgt direkt an das <code>Nm</code>-Modul beim Verlassen des <code>Repeat Message State</code>.</p>"}], "trans": [{"from": "FIG-c0c9d70b71f0ac14", "to": "FIG-fd4855bed9d20f73", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Lebenslinien/Komponenten</strong>: Die separate Lebenslinie <code>Nm:Nm Callbacks</code> entfällt; Interaktionen erfolgen direkt mit der Lebenslinie <code>«module» Nm::Nm</code>. Beide Lebenslinienköpfe (<code>Nm::Nm</code>, <code>FrNm::FrNm</code>) erhalten das Stereotyp <code>«module»</code>.\n</li><li><strong>Zustandsübergang</strong>: Der Ausgangszustand vor dem Übergang wechselt von <code>Ready Sleep State</code> zu <code>Repeat Message State</code>.\n</li><li><strong>Aufgerufene Schnittstelle</strong>: Der Callback <code>Nm_BusSleepMode(Nm_ChannelHandleType)</code> wird ersetzt durch die Benachrichtigung <code>Nm_StateChangeNotification()</code>.\n</li><li><strong>Rückkehr-/Antwortnachricht</strong>: Die gestrichelte Rückkehrnachricht von <code>Nm</code> an <code>FrNm</code> trägt nun ebenfalls die Beschriftung <code>Nm_StateChangeNotification()</code>.\n</li></ul>"}]};
